-- Deeply nested, many-join, long CTE and expression-heavy queries
SELECT * FROM (SELECT * FROM (SELECT * FROM (SELECT * FROM (SELECT id FROM users) a) b) c) d;
SELECT ((((1 + 2) * 3) - 4) / 5) AS v, -(-1), NOT NOT TRUE, !0, ~5, 1 + 2 * 3 - 4 % 3;
SELECT a FROM t WHERE (a = 1 OR b = 2) AND (c = 3 OR (d = 4 AND (e = 5 OR f = 6)));
SELECT a FROM t WHERE a = 1 OR b = 2 AND c = 3;
SELECT a FROM t WHERE NOT a = 1 AND b BETWEEN 1 AND 5 OR c IN (1, 2) AND d IS NOT NULL;
SELECT 1 << 2, 8 >> 1, 5 & 3, 5 | 3, 5 ^ 3, 'a' || 'b', 'a' && 'b';
SELECT IF(a > 1, IF(b > 2, 'x', 'y'), CASE WHEN c THEN 'z' ELSE NULL END) FROM t;
SELECT CASE status WHEN 'a' THEN 1 WHEN 'b' THEN 2 ELSE 3 END FROM t;
SELECT COALESCE(NULLIF(a, ''), b, c, 'default') FROM t;
SELECT * FROM t WHERE (a, b) IN ((1, 2), (3, 4));
SELECT * FROM t WHERE (a, b) = (SELECT x, y FROM u LIMIT 1);
SELECT * FROM t WHERE a = ANY (SELECT x FROM u) AND b > ALL (SELECT y FROM v) AND c = SOME (SELECT z FROM w);
SELECT * FROM t WHERE a > (SELECT MAX(x) FROM u WHERE u.k = t.k AND u.d > (SELECT MIN(d) FROM v WHERE v.k = u.k));
SELECT a.id, b.id, c.id, d.id, e.id, f.id FROM a JOIN b ON b.a_id = a.id JOIN c ON c.b_id = b.id LEFT JOIN d ON d.c_id = c.id LEFT JOIN e ON e.d_id = d.id RIGHT JOIN f ON f.e_id = e.id WHERE a.x = 1;
SELECT * FROM a LEFT OUTER JOIN b ON a.id = b.id RIGHT OUTER JOIN c ON b.id = c.id INNER JOIN d ON c.id = d.id;
WITH c1 AS (SELECT id, v FROM t1), c2 AS (SELECT id, v FROM t2 WHERE id IN (SELECT id FROM c1)), c3 AS (SELECT c1.id, c1.v + c2.v AS s FROM c1 JOIN c2 USING (id)), c4 AS (SELECT id, s, SUM(s) OVER (ORDER BY id) AS run FROM c3), c5 AS (SELECT * FROM c4 WHERE run > 10) SELECT * FROM c5 ORDER BY id LIMIT 10;
WITH cte (a, b) AS (SELECT 1, 2 UNION ALL SELECT 3, 4) SELECT * FROM cte;
SELECT t.* FROM t WHERE t.id IN (SELECT id FROM (SELECT id FROM u ORDER BY id DESC LIMIT 5) AS x);
SELECT COUNT(*) FROM (SELECT DISTINCT a, b FROM t) AS d;
(SELECT 1) UNION (SELECT 2) ORDER BY 1 LIMIT 1;
SELECT a FROM t1 INTERSECT SELECT a FROM t2;
SELECT a FROM t1 EXCEPT SELECT a FROM t2;
SELECT a, b, COUNT(*) FROM t GROUP BY a, b WITH ROLLUP HAVING COUNT(*) > 1 ORDER BY a DESC, b ASC LIMIT 10 OFFSET 5;
SELECT a FROM t ORDER BY FIELD(a, 'x', 'y', 'z'), RAND() LIMIT 3;
SELECT a FROM t GROUP BY a ORDER BY NULL;
SELECT SUM(DISTINCT a), COUNT(DISTINCT a, b), AVG(a), MIN(a), MAX(a), STDDEV(a), VARIANCE(a), BIT_OR(a), GROUP_CONCAT(a SEPARATOR '|') FROM t;
SELECT x FROM t WHERE x REGEXP BINARY 'A' AND y SOUNDS LIKE 'z' AND w LIKE 'a\_%' ESCAPE '\\';
SELECT a AS 'alias with space', b "other alias" FROM t;
SELECT t.a, t2.* FROM db1.t JOIN db2.t2 ON t.id = t2.id;
SELECT `db`.`t`.`c` FROM `db`.`t`;
SELECT * FROM t PARTITION (p0, p1);
SELECT * FROM t1 JOIN t2 ON t1.a = t2.a AND t1.b <=> t2.b WHERE t1.c LIKE CONCAT('%', t2.d, '%');
SELECT * FROM t FOR SHARE;
SELECT * FROM t FOR UPDATE NOWAIT;
